def _repartir(pesos, total):
    """Reparte `total` en enteros proporcionales a `pesos` que suman exactamente `total` (mayor resto)."""
    suma = sum(pesos)
    if not pesos or suma <= 0 or total <= 0:
        return [Decimal(0)] * len(pesos)
    exactos = [p * total / suma for p in pesos]
    pisos = [e.to_integral_value(rounding=ROUND_FLOOR) for e in exactos]
    faltan = int(total - sum(pisos))
    for i in sorted(range(len(pesos)), key=lambda i: (pisos[i] - exactos[i], i))[:faltan]:
        pisos[i] += 1
    return pisos


def repartir_descuentos_antiguos(apps, schema_editor):
    """Las ventas anteriores no guardaban el descuento por producto: se les reparte el descuento total
    de la venta (subtotal - total) en proporción al valor de cada línea, para que todo cuadre."""
    Venta = apps.get_model("inventario", "Venta")
    VentaItem = apps.get_model("inventario", "VentaItem")
    for v in Venta.objects.all():
        items = list(VentaItem.objects.filter(venta=v).order_by("id"))
        descuento = Decimal(v.subtotal) - Decimal(v.total)
        if not items or descuento <= 0:
            continue
        partes = _repartir([Decimal(i.cantidad) * Decimal(i.precio_unitario) for i in items], descuento)
        for it, parte in zip(items, partes):
            it.descuento = parte
            it.save(update_fields=["descuento"])


